  }
  return result;
}

function kemePlusGrand(tab, k) {
  const distinct = [...new Set(tab)];
  distinct.sort((a, b) => b - a);
  return distinct[k - 1];
}

function compteurFrequence(tab) {
  const freq = {};
  for (let item of tab) {
    if (!freq[item]) {
      freq[item] = 1;
    } else {
      freq[item]++;
    }
  }
  return freq;
}

function exponentiationRapide(x, n) {
  let result = 1;
  let base = x;
  while (n > 0) {
    if (n % 2 === 1) {
      result *= base;
    }
    base *= base;
    n = Math.floor(n / 2);
  }
  return result;
}

function sousTableauMax(tab) {
  let maxSum = tab[0];
  let currentSum = tab[0];
  for (let i = 1; i < tab.length; i++) {
    currentSum = Math.max(tab[i], currentSum + tab[i]);
    maxSum = Math.max(maxSum, currentSum);
  }
  return maxSum;
}
